import unittest
from candidate import parse_nested_parens

class TestParseNestedParens(unittest.TestCase):
    def test_normal_case_multiple_groups(self):
        self.assertEqual(parse_nested_parens('(()()) ((())) () ((())()())'), [2, 3, 1, 3])

    def test_single_group(self):
        self.assertEqual(parse_nested_parens('(()())'), [2])

    def test_single_level_group(self):
        self.assertEqual(parse_nested_parens('()'), [1])

    def test_deeply_nested_group(self):
        self.assertEqual(parse_nested_parens('((()))'), [3])

    def test_mixed_nested_levels(self):
        self.assertEqual(parse_nested_parens('(())(())(()())'), [2, 2, 3])

    def test_empty_string(self):
        self.assertEqual(parse_nested_parens(''), [])

    def test_none_input(self):
        with self.assertRaises(TypeError):
            parse_nested_parens(None)

    def test_non_string_input(self):
        with self.assertRaises(TypeError):
            parse_nested_parens(123)

    def test_string_with_spaces_only(self):
        self.assertEqual(parse_nested_parens('   '), [])

    def test_unbalanced_parens(self):
        self.assertEqual(parse_nested_parens('(()'), [1])  # Only counts up to first unmatched '('

    def test_negative_depth_handling(self):
        self.assertEqual(parse_nested_parens('(()())'), [2])

    def test_multiple_spaces_between_groups(self):
        self.assertEqual(parse_nested_parens('(()())   ((()))'), [2, 3])

    def test_mixed_content_with_parens(self):
        self.assertEqual(parse_nested_parens('(a(b)c)'), [1])  # Only counts parentheses

    def test_all_closed_parens(self):
        self.assertEqual(parse_nested_parens(')()()'), [1])

    def test_all_open_parens(self):
        self.assertEqual(parse_nested_parens('((((('), [4])

    def test_single_open_paren(self):
        self.assertEqual(parse_nested_parens('('), [1])

    def test_whitespace_only(self):
        self.assertEqual(parse_nested_parens(' \t\n\r '), [])

    def test_mixed_valid_invalid_groups(self):
        self.assertEqual(parse_nested_parens('(()()) () (()'), [2, 1, 1])
